function spyCorrections(item){return Array.isArray(item[1])?item[1]:[]}
function spyTargets(tokens,item){return spyCorrections(item).map((pair,key)=>({key,from:pair[0],to:pair[1],index:tokens.findIndex(t=>t.includes(pair[0]))})).filter(x=>x.index>=0)}
function spySound(kind){if(!spy.sound)return;try{spy.audio=spy.audio||new (window.AudioContext||window.webkitAudioContext)();const ctx=spy.audio,now=ctx.currentTime,notes={open:[[520,0,.09],[780,.06,.12]],ok:[[660,0,.1],[880,.08,.1],[1320,.16,.18]],bad:[[220,0,.16],[180,.1,.18]],fix:[[520,0,.08],[700,.07,.08],[940,.14,.08],[1250,.21,.2]],bingo:[[523,0,.12],[659,.1,.12],[784,.2,.12],[1047,.3,.3]],pick:[[420,0,.05]]}[kind]||[];notes.forEach(([f,t,d])=>{const o=ctx.createOscillator(),g=ctx.createGain();o.type=kind==="bad"?"triangle":"sine";o.frequency.setValueAtTime(f,now+t);g.gain.setValueAtTime(.0001,now+t);g.gain.exponentialRampToValueAtTime(.16,now+t+.015);g.gain.exponentialRampToValueAtTime(.0001,now+t+d);o.connect(g).connect(ctx.destination);o.start(now+t);o.stop(now+t+d+.05)})}catch(e){}}
function spyFxSize(){const c=$("#spyFx"),r=window.devicePixelRatio||1;c.width=innerWidth*r;c.height=innerHeight*r;c.getContext("2d").setTransform(r,0,0,r,0,0)}
function spyBurst(x,y,count,colors,power=1,confetti=false){if(reduceMotion)return;for(let i=0;i<count;i++){const a=confetti?Math.PI/2+(Math.random()-.5)*1.2:Math.random()*Math.PI*2,v=(confetti?3+Math.random()*5:2+Math.random()*5)*power;spy.particles.push({x:confetti?Math.random()*innerWidth:x,y:confetti?-20-Math.random()*120:y,vx:Math.cos(a)*v*(confetti?.5:1),vy:confetti?Math.random()*2:Math.sin(a)*v-2,life:confetti?160+Math.random()*80:50+Math.random()*30,age:0,size:confetti?6+Math.random()*6:3+Math.random()*4,color:colors[i%colors.length],rot:Math.random()*6,spin:(Math.random()-.5)*.3,shape:confetti||Math.random()<.4?"rect":"star"})}if(!spy.raf)spy.raf=requestAnimationFrame(spyTick)}
function spyTick(){const c=$("#spyFx"),ctx=c.getContext("2d");ctx.clearRect(0,0,innerWidth,innerHeight);spy.particles=spy.particles.filter(p=>p.age<p.life);spy.particles.forEach(p=>{p.age++;p.vy+=.12;p.vx*=.985;p.x+=p.vx;p.y+=p.vy;p.rot+=p.spin;ctx.save();ctx.globalAlpha=Math.max(0,1-p.age/p.life);ctx.translate(p.x,p.y);ctx.rotate(p.rot);ctx.fillStyle=p.color;if(p.shape==="rect")ctx.fillRect(-p.size/2,-p.size/4,p.size,p.size/2);else{ctx.beginPath();for(let k=0;k<10;k++){const r=k%2?p.size*.45:p.size;ctx.lineTo(Math.cos(k*Math.PI/5)*r,Math.sin(k*Math.PI/5)*r)}ctx.closePath();ctx.fill()}ctx.restore()});spy.raf=spy.particles.length?requestAnimationFrame(spyTick):0}
function spyCenter(el){const r=el.getBoundingClientRect();return[r.left+r.width/2,r.top+r.height/2]}
function spyMsg(text,type){const el=$("#spyCaseMsg");el.textContent=text;el.classList.remove("ok","bad");if(type){void el.offsetWidth;el.classList.add(type)}}
