function renderSpyLines(animateIndex){const svg=$("#spyLines"),pos=[50,150,250];svg.classList.toggle("all-done",spy.used.every(Boolean)&&animateIndex===false);svg.innerHTML=spy.lines.map((entry,k)=>{const l=SPY_LINES[entry.line],a=l[0],z=l[2],x1=pos[a%3],y1=pos[Math.floor(a/3)],x2=pos[z%3],y2=pos[Math.floor(z/3)],ex=(x2-x1)*.14,ey=(y2-y1)*.14;return'<line class="'+entry.owner+(k===animateIndex?' draw':'')+'" x1="'+(x1-ex)+'" y1="'+(y1-ey)+'" x2="'+(x2+ex)+'" y2="'+(y2+ey)+'" pathLength="1" vector-effect="non-scaling-stroke"/>'}).join("")}
function updateSpyHud(){const mine=spy.status.filter(x=>x==="player").length,played=spy.used.filter(Boolean).length,myLines=spy.lines.filter(x=>x.owner==="player").length;$("#spySolved").textContent=mine;$("#spyBingo").textContent=myLines;$("#spyMeter").style.width=(played/data.spy.length*100)+"%";const turn=$("#spyTurn");if(turn){turn.textContent=spy.turn==="player"?"나의 차례":"젤리코치의 차례";turn.classList.toggle("coach",spy.turn==="coach")}}
