function openSpyCase(i){const tile=$('.spy-tile[data-index="'+i+'"]'),done=Boolean(spy.used[i]),owner=spy.status[i];if(!done&&spy.turn!=="player"){showToast("젤리코치가 칸을 고르고 있어요.");return}spy.current=i;spy.locateMiss=0;spy.found=new Set();spy.phase=done?"review":"locate";$("#spyCaseNo").textContent=i+1;$("#spyCaseKicker").textContent=done?(owner==="player"?"내가 얻은 칸":owner==="coach"?"젤리코치가 얻은 칸":"아무도 얻지 않은 칸"):"나의 차례";$("#spyCaseTitle").textContent=done?"바르게 고친 문장이에요":"잘못 읽힌 낱말을 모두 눌러요";renderSpySentence(done);$("#spyStamp").className="spy-stamp";$("#spyJudge").classList.add("hidden");$("#spyNext").classList.toggle("hidden",!done);$("#spyNext").textContent="보드로 돌아가기";$("#spyPeekPanel").classList.add("hidden");$("#spyPeek").textContent="본문 살짝 보기";const count=spyCorrections(data.spy[i]).length,doneMsg=owner==="player"?"잘못 읽힌 낱말을 모두 찾았어요.":owner==="coach"?"젤리코치가 고른 문장을 확인해 봐요.":"이 칸은 중립으로 남았어요. 바르게 고친 문장을 확인해 봐요.";spyMsg(done?doneMsg:"바뀐 낱말 "+count+"곳을 찾아요.",done?"ok":"");const modal=$("#spyModal"),card=$("#spyCase");modal.classList.remove("hidden","closing");modal.setAttribute("aria-hidden","false");tile.classList.add("opening");spySound("open");if(!reduceMotion&&card.animate){const t=tile.getBoundingClientRect(),c=card.getBoundingClientRect();card.animate([{transform:"translate("+(t.left+t.width/2-c.left-c.width/2)+"px,"+(t.top+t.height/2-c.top-c.height/2)+"px) scale("+(t.width/c.width)+","+(t.height/c.height)+") rotateY(90deg)",opacity:.3,borderRadius:"30px"},{transform:"none",opacity:1,borderRadius:"26px"}],{duration:520,easing:"cubic-bezier(.2,.9,.25,1.12)"});$$(".spy-word",card).forEach(w=>w.classList.add("enter"))}setTimeout(()=>tile.classList.remove("opening"),520);if(!done)$(".spy-word",card)?.focus({preventScroll:true});log("spy_open","spy-"+i,{review:done,owner:owner||"neutral"})}
function closeSpyCase(instant){const modal=$("#spyModal");if(modal.classList.contains("hidden"))return;const i=spy.current,tile=$('.spy-tile[data-index="'+i+'"]'),card=$("#spyCase"),finish=()=>{if(modal.classList.contains("hidden"))return;modal.classList.add("hidden");modal.classList.remove("closing");modal.setAttribute("aria-hidden","true");if(spy.phase==="solved"||spy.phase==="neutral"){spy.phase="";celebrateSpyTile(i)}};if(instant||reduceMotion||!card.animate||!tile){finish();return}const t=tile.getBoundingClientRect(),c=card.getBoundingClientRect();modal.classList.add("closing");setTimeout(finish,480);card.animate([{transform:"none",opacity:1},{transform:"translate("+(t.left+t.width/2-c.left-c.width/2)+"px,"+(t.top+t.height/2-c.top-c.height/2)+"px) scale("+(t.width/c.width)+","+(t.height/c.height)+")",opacity:0}],{duration:380,easing:"cubic-bezier(.5,0,.75,0)"}).onfinish=finish}
function pickSpyWord(k,w){if(spy.phase!=="locate")return;const item=data.spy[spy.current],tokens=item[0].split(/\s+/),targets=spyTargets(tokens,item),hit=targets.find(x=>x.index===k&&!spy.found.has(x.key));if(!hit)assistItem("spy-"+spy.current).tries++;log("answer","spy-"+spy.current,{step:"locate",response:w.textContent,correct:Boolean(hit),found:spy.found.size});if(!hit){spy.locateMiss++;spy.attempts[spy.current]=(spy.attempts[spy.current]||0)+1;w.classList.add("miss");spyShake($("#spyCase"));spySound("bad");renderSpySentence(true);spyStamp("중립 칸","neutral");spyMsg("이 낱말은 바뀌지 않았어요. 이 칸은 아무도 얻지 않고, 코치는 다른 칸을 골라요.","bad");$("#spyCaseKicker").textContent="아무도 얻지 않은 칸";$("#spyCaseTitle").textContent="바뀐 낱말을 함께 확인해요";noteHelp("spy-"+spy.current,"A4","answer-reveal","error");itemResult("spy-"+spy.current,{outcome:"missed"});spyResolve(null);return}spy.found.add(hit.key);spySound("fix");const before=w.textContent,after=before.replace(hit.from,hit.to);w.innerHTML='<span class="spy-old">'+escapeHTML(before)+'</span><span class="spy-new">'+escapeHTML(after)+'</span>';w.classList.add("fixed-static");w.disabled=true;const [x,y]=spyCenter(w);spyBurst(x,y,26,["#16a37f","#ffd45c","#7a4fe0","#42c5d8"],.9);const remaining=targets.length-spy.found.size;if(remaining){spyMsg("찾았어요! 아직 "+remaining+"곳이 남았어요.","ok");return}spyStamp("나의 칸","fix");spyMsg("잘못 읽힌 낱말을 모두 찾았어요. 내가 이 칸을 얻었어요!","ok");$("#spyCaseKicker").textContent="내가 얻은 칸";$("#spyCaseTitle").textContent="문장을 바르게 고쳤어요";itemResult("spy-"+spy.current,{outcome:"found-all"});spyResolve("player")}
