function spyCoachChoice(){const open=spy.used.map((used,i)=>used?-1:i).filter(i=>i>=0);if(!open.length)return-1;const lineChoice=owner=>{for(const line of SPY_LINES){const owned=line.filter(i=>spy.status[i]===owner).length,candidates=line.filter(i=>!spy.used[i]);if(owned===2&&candidates.length===1)return candidates[0]}return-1};const winning=lineChoice("coach"),blocking=lineChoice("player");if(winning>=0)return winning;if(blocking>=0)return blocking;if(open.includes(4))return 4;for(const i of[0,2,6,8])if(open.includes(i))return i;return open[0]}
function spyCoachTakeTurn(){const i=spyCoachChoice();if(i<0){spyFinale();return}spy.turn="coach";renderSpyBoard();feedback($("#spyFeedback"),"젤리코치가 다른 빈칸을 고르고 있어요.");setTimeout(()=>{spy.current=i;spy.status[i]="coach";spy.used[i]=true;spy.phase="";spySound("pick");celebrateSpyTile(i)},reduceMotion?80:700)}
