function counselAnswer(i,btn){const C=data.counsel,g=C.guests[counselIndex];if(!g)return;const id="problem-solver-"+(counselIndex+1),a=assistItem(id);if(a.done)return;a.tries++;const correct=i===g.a;log("answer",id,{response:i,correct,attempt:a.tries});
  if(!correct){btn.disabled=true;btn.classList.add("no");counselFace(2);const rc=$("#counselReact");if(rc){rc.textContent=g.no||"음… 아닌 것 같아";rc.classList.remove("show");void rc.offsetWidth;rc.classList.add("show")}setTimeout(()=>{if(!assistItem(id).done)counselFace(4)},1400);const st=$(".counsel-stage");st.classList.remove("shake");void st.offsetWidth;st.classList.add("shake");
    feedback($("#classifyFeedback"),g.hint||"문제를 다시 읽고, 글에서 배운 것을 떠올려 봐요.","bad");const bar=helpBar("classifyHelp",$("#classifyFeedback"));bar.innerHTML="";
    if(g.ev)bar.append(helpButton("글에서 찾아보기","A3","evidence-sentence",id,()=>{feedback($("#classifyFeedback"),"글에서: 「"+g.ev+"」","")}));
    if(a.tries>=2)bar.append(helpButton("알맞은 답 보기","A4","answer-reveal",id,()=>$$(".counsel-opt")[g.a].classList.add("reveal")));return}
  itemResult(id);$$(".counsel-opt").forEach(b=>b.disabled=true);btn.classList.add("yes");counselFace(5);$("#counselBubble").textContent=g.thanks||"고마워! 이제 알겠어!";$(".counsel-stage").classList.add("happy");
  const hb=$("#classifyHelp");if(hb)hb.innerHTML="";feedback($("#classifyFeedback"),"문제 해결! "+g.name+"의 얼굴이 밝아졌어요.","ok");
  const next=document.createElement("button");next.type="button";next.className="counsel-next";next.textContent=counselIndex+1<C.guests.length?"다음 친구 만나기":"해결 임무 마치기";next.onclick=()=>{counselIndex++;counselShow()};$("#counselOpts").append(next)}
function hintOnOpenOnly(btn,isOpen){if(!btn||btn.dataset.hintOnOpen)return;btn.dataset.hintOnOpen="1";const set=()=>{if(isOpen())btn.removeAttribute("data-track");else btn.dataset.track="hint"};btn.addEventListener("pointerdown",set,true);btn.addEventListener("keydown",e=>{if(e.key==="Enter"||e.key===" ")set()},true)}
document.addEventListener("DOMContentLoaded",()=>{hintOnOpenOnly($("#passageToggle"),()=>$("#readingPaper").classList.contains("peek"));hintOnOpenOnly($("#spyPeek"),()=>!$("#spyPeekPanel").classList.contains("hidden"))});
/* 단어장: 눌러 본 낱말이 저절로 담김(폴더 단위로 쌓임) */
const WB_KEY=LID+":wordbook";
function wordbookGet(){try{return JSON.parse(localStorage.getItem(WB_KEY)||"[]")}catch(e){return[]}}
function wordbookAdd(v){const wb=wordbookGet();if(wb.some(x=>x.w===v[0]))return false;wb.push({w:v[0],h:v[1]||"",m:v[2]||"",e:v[3]||"",s:SID,t:(data.meta&&data.meta.title)||""});try{localStorage.setItem(WB_KEY,JSON.stringify(wb))}catch(e){}wordbookCount();return true}
function wordbookCount(){const b=$("#wordbookButton");if(b)b.innerHTML="📒 단어장 <b>"+wordbookGet().length+"</b>"}
function openWordbook(){const wb=wordbookGet(),list=$("#wordbookList");list.innerHTML=wb.length?wb.slice().reverse().map(x=>{const parts=x.h.split("·"),hj=/[\u4e00-\u9fff]/.test(parts[0])?parts[0].trim():"";return '<li><details><summary><b>'+escapeHTML(x.w)+'</b>'+(hj?'<span class="wb-hanja">'+escapeHTML(hj)+'</span>':'')+'<small>'+escapeHTML(x.m)+'</small></summary>'+(hj&&parts[1]?'<p class="wb-gloss">'+escapeHTML(parts.slice(1).join("·").trim())+'</p>':'')+'<p class="wb-ex">'+escapeHTML(x.e)+'</p></details></li>'}).join(""):'<li class="wb-empty">아직 담긴 낱말이 없어요. 글에서 점선이 그어진 낱말을 눌러 보세요.</li>';$("#wordbookDialog").classList.remove("hidden");log("wordbook_open","wordbook",{count:wb.length})}
document.addEventListener("DOMContentLoaded",()=>{const tools=$(".footer-tools");if(tools&&!$("#wordbookButton")){const b=document.createElement("button");b.type="button";b.id="wordbookButton";b.className="wordbook-button";b.onclick=openWordbook;tools.insertBefore(b,tools.children[1]||null)}
  if(!$("#wordbookDialog")){const d=document.createElement("div");d.className="vocab-dialog wordbook-dialog hidden";d.id="wordbookDialog";d.innerHTML='<section role="dialog" aria-modal="true" aria-labelledby="wordbookTitle"><button class="vocab-close" id="wordbookClose" aria-label="닫기">×</button><small>내가 찾아본 낱말</small><h2 id="wordbookTitle">📒 나의 단어장</h2><ul class="wordbook-list" id="wordbookList"></ul></section>';document.body.append(d);d.onclick=e=>{if(e.target===d)d.classList.add("hidden")};$("#wordbookClose").onclick=()=>d.classList.add("hidden")}
  wordbookCount()});
