function propHTML(e){const src=PROP_IMG[e];return src?'<img src="'+src+'" alt="">':escapeHTML(e||"")}
function showParaPic(i){const box=$("#readingCoachPanel");if(!box)return;let wrap=$("#paraPic");if(!wrap){wrap=document.createElement("div");wrap.id="paraPic";wrap.className="para-pic";const btn=$("#readingDone");box.insertBefore(wrap,btn)}const list=((data.pictures&&data.pictures.paras)||{})[String(i)]||[];wrap.innerHTML=list.map(src=>'<img src="'+escapeHTML(src)+'" alt="">').join("");wrap.hidden=!list.length}
